// File storage for built EPUBs, page images and editor images.
//
// Two implementations with the same methods:
// - DiskBlobs: files in a folder on this computer (the app on your Mac, and
//   tests). Keys map straight to paths under the folder, so the files are where
//   they have always been.
// - S3Blobs: an S3-compatible bucket (Backblaze B2 for Render installs,
//   Cloudflare R2 for Cloudflare installs), for hosted installs whose own disk
//   does not last.
//
// Keys are relative paths like "users/<owner>/out/<id>-Book.epub". They are
// generated by the app, but checked anyway so none can climb out of its place.

import fs from 'node:fs/promises';
import path from 'node:path';
import { AwsClient } from 'aws4fetch';

/** Throw unless `key` is a plain relative path with no climbing out. */
export function checkKey(key) {
  const text = String(key || '');
  if (
    !text ||
    text.length > 900 ||
    text.startsWith('/') ||
    text.includes('\\') ||
    text.includes('\0') ||
    text.split('/').some((part) => part === '' || part === '.' || part === '..')
  ) {
    throw new Error(`Invalid storage key: ${text.slice(0, 120)}`);
  }
  return text;
}

export class DiskBlobs {
  /** @param {string} root Folder the keys are relative to. */
  constructor(root) {
    this.root = path.resolve(root);
    // Listing a folder is cheap, so a library can check its files exist.
    this.cheapExists = true;
  }

  /** The file a key names. */
  localPath(key) {
    const target = path.resolve(this.root, checkKey(key));
    if (!target.startsWith(this.root + path.sep)) throw new Error('Invalid storage key.');
    return target;
  }

  async get(key) {
    try {
      return await fs.readFile(this.localPath(key));
    } catch (err) {
      if (err.code === 'ENOENT') return null;
      throw err;
    }
  }

  async put(key, data) {
    const target = this.localPath(key);
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, data);
  }

  async exists(key) {
    try {
      await fs.access(this.localPath(key));
      return true;
    } catch {
      return false;
    }
  }

  async delete(key) {
    await fs.rm(this.localPath(key), { force: true });
  }

  /** Delete everything under a key prefix that names a folder ("x/pages"). */
  async deletePrefix(prefix) {
    await fs.rm(this.localPath(prefix), { recursive: true, force: true });
  }

  /** Total bytes under a prefix (a folder), for storage limits. */
  async size(prefix) {
    let total = 0;
    async function walk(dir) {
      let entries;
      try {
        entries = await fs.readdir(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) await walk(full);
        else total += (await fs.stat(full).catch(() => ({ size: 0 }))).size;
      }
    }
    await walk(prefix ? this.localPath(prefix) : this.root);
    return total;
  }
}

/**
 * An S3-compatible bucket. Requests are signed with AWS Signature V4 (via the
 * small aws4fetch library) and addressed path-style, which both B2 and R2
 * accept.
 */
export class S3Blobs {
  /**
   * @param {{endpoint: string, bucket: string, accessKeyId: string, secretAccessKey: string, region?: string, prefix?: string, fetch?: Function}} options
   */
  constructor({ endpoint, bucket, accessKeyId, secretAccessKey, region = 'auto', prefix = '', fetch: fetchImpl }) {
    if (!endpoint || !bucket || !accessKeyId || !secretAccessKey) {
      throw new Error('S3 storage needs an endpoint, bucket, access key ID and secret key.');
    }
    this.base = `${String(endpoint).replace(/\/+$/, '')}/${encodeURIComponent(bucket)}`;
    this.prefix = prefix ? `${checkKey(prefix)}/` : '';
    this.client = new AwsClient({ accessKeyId, secretAccessKey, region, service: 's3' });
    this.fetch = fetchImpl || globalThis.fetch;
    this.cheapExists = false;
  }

  #url(key, query = '') {
    const encoded = `${this.prefix}${checkKey(key)}`.split('/').map(encodeURIComponent).join('/');
    return `${this.base}/${encoded}${query}`;
  }

  async #send(url, init = {}) {
    const signed = await this.client.sign(url, init);
    return this.fetch(signed, { signal: AbortSignal.timeout(60000) });
  }

  async #fail(res, what) {
    const detail = (await res.text().catch(() => '')).slice(0, 300);
    const code = /<Code>([^<]+)<\/Code>/.exec(detail)?.[1] || res.statusText;
    return new Error(`File storage could not ${what} (HTTP ${res.status} ${code}).`);
  }

  async get(key) {
    const res = await this.#send(this.#url(key));
    if (res.status === 404) return null;
    if (!res.ok) throw await this.#fail(res, 'read a file');
    return Buffer.from(await res.arrayBuffer());
  }

  async put(key, data, contentType = 'application/octet-stream') {
    const res = await this.#send(this.#url(key), {
      method: 'PUT',
      body: data,
      headers: { 'content-type': contentType, 'content-length': String(data.length) },
    });
    if (!res.ok) throw await this.#fail(res, 'save a file');
  }

  async exists(key) {
    const res = await this.#send(this.#url(key), { method: 'HEAD' });
    if (res.status === 404) return false;
    if (!res.ok) throw await this.#fail(res, 'check a file');
    return true;
  }

  async delete(key) {
    const res = await this.#send(this.#url(key), { method: 'DELETE' });
    if (!res.ok && res.status !== 404) throw await this.#fail(res, 'delete a file');
  }

  /** Keys (relative to this store) and sizes under a prefix. */
  async list(prefix) {
    const full = prefix ? `${this.prefix}${checkKey(prefix)}/` : this.prefix;
    const found = [];
    let token = '';
    do {
      const query = `?list-type=2&prefix=${encodeURIComponent(full)}${token ? `&continuation-token=${encodeURIComponent(token)}` : ''}`;
      const res = await this.#send(`${this.base}${query}`);
      if (!res.ok) throw await this.#fail(res, 'list files');
      const xml = await res.text();
      for (const [, block] of xml.matchAll(/<Contents>([\s\S]*?)<\/Contents>/g)) {
        const key = unescapeXml(/<Key>([\s\S]*?)<\/Key>/.exec(block)?.[1] || '');
        const size = Number(/<Size>(\d+)<\/Size>/.exec(block)?.[1] || 0);
        if (key.startsWith(this.prefix)) found.push({ key: key.slice(this.prefix.length), size });
      }
      token = /<IsTruncated>true<\/IsTruncated>/.test(xml)
        ? unescapeXml(/<NextContinuationToken>([\s\S]*?)<\/NextContinuationToken>/.exec(xml)?.[1] || '')
        : '';
    } while (token);
    return found;
  }

  async deletePrefix(prefix) {
    for (const { key } of await this.list(prefix)) await this.delete(key);
  }

  async size(prefix) {
    return (await this.list(prefix)).reduce((n, f) => n + f.size, 0);
  }
}

function unescapeXml(text) {
  return text
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

/** A store for one owner: every key gets the owner's prefix. */
export class ScopedBlobs {
  constructor(blobs, prefix) {
    this.blobs = blobs;
    this.prefix = prefix ? checkKey(prefix) : '';
    this.cheapExists = blobs.cheapExists;
  }

  #key(key) {
    return this.prefix ? `${this.prefix}/${checkKey(key)}` : checkKey(key);
  }

  get(key) {
    return this.blobs.get(this.#key(key));
  }
  put(key, data, type) {
    return this.blobs.put(this.#key(key), data, type);
  }
  exists(key) {
    return this.blobs.exists(this.#key(key));
  }
  delete(key) {
    return this.blobs.delete(this.#key(key));
  }
  deletePrefix(prefix) {
    return this.blobs.deletePrefix(this.#key(prefix));
  }
  size(prefix) {
    return this.blobs.size(prefix ? this.#key(prefix) : this.prefix);
  }
  localPath(key) {
    return this.blobs.localPath?.(this.#key(key)) ?? null;
  }
}
